    /// <summary>
    /// The typed handler's resolution of <paramref name="entryId"/>, or null when it has none or leaves it null.
    /// The handler receives <paramref name="request"/> when it is of the entry's request type, and otherwise
    /// (the dictionary dispatch) a request of that type built from <paramref name="assertions"/>.
    /// </summary>
    internal static Resolution<object>? Dispatch(string entryId, RuleRequest assertions, IEntryRequest? request)
    {
        Resolution<object>? resolution = null;
        switch (entryId)
        {
            case "combat-rounds":
                CombatRounds(request as global::Srd52Combat.Requests.CombatRoundsRequest ?? new(assertions), ref resolution);
                break;
            case "round-duration":
                RoundDuration(request as global::Srd52Combat.Requests.RoundDurationRequest ?? new(assertions), ref resolution);
                break;
            case "next-round":
                resolution = NextRound(request as global::Srd52Combat.Requests.NextRoundRequest ?? new(assertions));
                break;
            case "combat-steps":
                resolution = CombatSteps(request as global::Srd52Combat.Requests.CombatStepsRequest ?? new(assertions));
                break;
            case "initiative-roll":
                resolution = InitiativeRoll(request as global::Srd52Combat.Requests.InitiativeRollRequest ?? new(assertions));
